/**
 * Enhanced Toast/Notification System
 * Provides accessible notifications with auto-dismiss
 */

import React, { createContext, useCallback, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  CheckCircle2,
  AlertCircle,
  Info,
  AlertTriangle,
  X,
} from "lucide-react";

/** Visual tone of a {@link Toast}, selecting its icon and colour gradient. */
export type ToastType = "success" | "error" | "info" | "warning";

/** A single notification queued by {@link ToastProvider}. */
export interface Toast {
  /** Unique identifier generated by `addToast`. */
  id: string;
  /** Visual tone of the notification. */
  type: ToastType;
  /** Bold headline text. */
  message: string;
  /** Optional secondary line of detail. */
  description?: string;
  /** Auto-dismiss delay in milliseconds; omitting it uses the provider default. */
  duration?: number;
  /** Optional inline action rendered as a link-style button. */
  action?: {
    /** Text shown on the action button. */
    label: string;
    /** Handler invoked when the action button is clicked. */
    onClick: () => void;
  };
}

/** Shape of the value exposed by {@link ToastContext}. */
interface ToastContextType {
  /** Notifications currently rendered in the stack. */
  toasts: Toast[];
  /** Queues a notification and returns the id assigned to it. */
  addToast: (toast: Omit<Toast, "id">) => string;
  /** Removes the notification with the given id. */
  removeToast: (id: string) => void;
}

/** React context carrying the toast queue; consume it through {@link useToast}. */
export const ToastContext = createContext<ToastContextType | undefined>(
  undefined,
);

const toastIcons: Record<ToastType, React.ReactNode> = {
  success: <CheckCircle2 className="h-5 w-5" />,
  error: <AlertCircle className="h-5 w-5" />,
  info: <Info className="h-5 w-5" />,
  warning: <AlertTriangle className="h-5 w-5" />,
};

const toastColors: Record<ToastType, string> = {
  success:
    "from-emerald-500/20 to-emerald-500/10 border-emerald-500/30 text-emerald-300",
  error: "from-red-500/20 to-red-500/10 border-red-500/30 text-red-300",
  info: "from-blue-500/20 to-blue-500/10 border-blue-500/30 text-blue-300",
  warning:
    "from-amber-500/20 to-amber-500/10 border-amber-500/30 text-amber-300",
};

/** Props accepted by {@link ToastItem}. */
interface ToastItemProps {
  /** Notification to render. */
  toast: Toast;
  /** Callback invoked by the timer and the dismiss button. */
  onClose: () => void;
}

/**
 * Renders one notification card, including its auto-dismiss timer and action button.
 *
 * @remarks
 * Client Component — no `"use client"` directive (Next.js Pages Router); relies on client-side state/effects, so it runs in the browser after hydration.
 *
 * @example
 * ```tsx
 * <ToastItem toast={toast} onClose={() => removeToast(toast.id)} />
 * ```
 */
function ToastItem({ toast, onClose }: ToastItemProps) {
  React.useEffect(() => {
    if (!toast.duration) return;
    const timer = setTimeout(onClose, toast.duration);
    return () => clearTimeout(timer);
  }, [toast.duration, onClose]);

  return (
    <motion.div
      initial={{ opacity: 0, y: -10, x: 0 }}
      animate={{ opacity: 1, y: 0, x: 0 }}
      exit={{ opacity: 0, y: -10, x: 100 }}
      className={`glass-effect rounded-lg border p-4 flex gap-3 items-start bg-gradient-to-r ${toastColors[toast.type]} backdrop-blur-sm`}
      role="alert"
      aria-live="polite"
    >
      <div className="flex-shrink-0 mt-0.5">{toastIcons[toast.type]}</div>
      <div className="flex-1 min-w-0">
        <p className="font-medium text-sm">{toast.message}</p>
        {toast.description && (
          <p className="text-xs opacity-75 mt-1">{toast.description}</p>
        )}
        {toast.action && (
          <button
            onClick={toast.action.onClick}
            className="text-xs font-medium mt-2 hover:underline focus:outline-none focus:ring-2 focus:ring-offset-2 rounded px-1"
          >
            {toast.action.label}
          </button>
        )}
      </div>
      <button
        onClick={onClose}
        className="flex-shrink-0 opacity-60 hover:opacity-100 transition-opacity focus:outline-none focus:ring-2 focus:ring-offset-2 rounded p-1"
        aria-label="Dismiss notification"
      >
        <X className="h-4 w-4" />
      </button>
    </motion.div>
  );
}

/** Props accepted by {@link ToastProvider}. */
interface ToastProviderProps {
  /** Application subtree that may call {@link useToast}. */
  children: React.ReactNode;
}

/**
 * Provides the toast queue to the app tree and renders the animated notification stack.
 *
 * @remarks
 * Client Component — no `"use client"` directive (Next.js Pages Router); relies on client-side state/effects, so it runs in the browser after hydration.
 *
 * @example
 * ```tsx
 * // Mounted once in _app.tsx, around the routed page.
 * <ToastProvider>
 *   <Component {...pageProps} />
 * </ToastProvider>
 * ```
 */
export function ToastProvider({ children }: ToastProviderProps) {
  const [toasts, setToasts] = useState<Toast[]>([]);

  const addToast = useCallback((toast: Omit<Toast, "id">) => {
    const id = Math.random().toString(36).substr(2, 9);
    const newToast: Toast = { ...toast, id, duration: toast.duration ?? 4000 };
    setToasts((prev) => [...prev, newToast]);
    return id;
  }, []);

  const removeToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  return (
    <ToastContext.Provider value={{ toasts, addToast, removeToast }}>
      {children}
      <div className="fixed bottom-4 right-4 z-50 flex flex-col gap-2 max-w-sm pointer-events-none">
        <AnimatePresence mode="popLayout">
          {toasts.map((toast) => (
            <div key={toast.id} className="pointer-events-auto">
              <ToastItem toast={toast} onClose={() => removeToast(toast.id)} />
            </div>
          ))}
        </AnimatePresence>
      </div>
    </ToastContext.Provider>
  );
}

/**
 * Reads the toast queue and its mutators from the nearest {@link ToastProvider}.
 *
 * @returns The queued `toasts` plus `addToast` (returns the new id and applies a default `duration` of 4000 ms) and `removeToast`.
 * @throws {@link Error} When called outside a {@link ToastProvider}.
 *
 * @example
 * ```tsx
 * const { addToast } = useToast();
 * addToast({ type: 'success', message: 'Product saved' });
 * ```
 */
export function useToast() {
  const context = React.useContext(ToastContext);
  if (!context) {
    throw new Error("useToast must be used within ToastProvider");
  }
  return context;
}
